int main() {
    int n = (int)readInt();
    long long k = readInt();
    vector<long long> r(n), h(n);
    for (auto &x : r) x = readInt();
    for (auto &x : h) x = readInt();
    // Each server is a job of length ceil(health / k) with weight request.
    vector<pair<long long, long long>> jobs(n);
    for (int i = 0; i < n; i++) jobs[i] = {(h[i] + k - 1) / k, r[i]};
    // Smith's rule: ascending length / weight, compared by cross products.
    stable_sort(jobs.begin(), jobs.end(), [](const auto &a, const auto &b) {
