import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        long[] r = new long[n], h = new long[n];
        for (int i = 0; i < n; i++) r[i] = nextLong();
        for (int i = 0; i < n; i++) h[i] = nextLong();
        long[][] jobs = new long[n][];
        for (int i = 0; i < n; i++) jobs[i] = new long[] {(h[i] + k - 1) / k, r[i]};
        Arrays.sort(jobs, (a, b) -> Long.compare(a[0] * b[1], b[0] * a[1]));
        long elapsed = 0, answer = 1;
        for (long[] job : jobs) {
            elapsed += job[0];
            answer += elapsed * job[1];
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	r := make([]int, n)
	for i := range r {
		r[i] = nextInt()
	}
	jobs := make([][2]int, n)
	for i := range jobs {
		jobs[i] = [2]int{(nextInt() + k - 1) / k, r[i]}
	}
	sort.SliceStable(jobs, func(i, j int) bool {
		return jobs[i][0]*jobs[j][1] < jobs[j][0]*jobs[i][1]
	})
	elapsed, answer := 0, 1
	for _, job := range jobs {
		elapsed += job[0]
		answer += elapsed * job[1]
	}
	fmt.Println(answer)
}
